    private ItemStackHandler createHandler(int size, int dataId) {
        return new ItemStackHandler(size) {
            @Override
            protected void onContentsChanged(int slot) {
                setSlotChanged(slot, getStackInSlot(slot), dataId);

                if(dataId == TOOLS_ID) {
                    sendDataToClients(ModDataHelper.TOOLS_CONTAINER);
                }

                //Update comparator
                saveHandler.run();
            }

            @Override
            public boolean isItemValid(int slot, @NotNull ItemStack stack) {
                if(dataId == TOOLS_ID) {
                    return ToolSlotItemHandler.isValid(stack);
                }
                return BackpackSlotItemHandler.isItemValid(stack);
            }
        };
    }

    public void setSlotChanged(int index, ItemStack stack, int dataId) {
        switch(dataId) {
            case STORAGE_ID:
                NbtHelper.update(this.stack, ModDataHelper.BACKPACK_CONTAINER, this.getStorage().getSlots(), index, stack);
                break;
            case UPGRADES_ID:
                NbtHelper.update(this.stack, ModDataHelper.UPGRADES, this.getUpgrades().getSlots(), index, stack);
                break;
            case TOOLS_ID:
                NbtHelper.update(this.stack, ModDataHelper.TOOLS_CONTAINER, this.getTools().getSlots(), index, stack);
                break;
        }
    }

    public void applyLowestTickInterval() {
        int minimalTickInterval = 100;
        for(int i = 0; i < this.upgrades.getSlots(); i++) {
            ItemStack upgrade = this.upgrades.getStackInSlot(i);
            if(!upgrade.isEmpty()) {
                if(NbtHelper.getOrDefault(upgrade, ModDataHelper.UPGRADE_ENABLED, true) && NbtHelper.has(upgrade, ModDataHelper.COOLDOWN)) {
                    minimalTickInterval = Math.min(minimalTickInterval, NbtHelper.get(upgrade, ModDataHelper.COOLDOWN));
                }
            }
        }
        if(!canUpgradeTick() || minimalTickInterval != getUpgradeTickInterval()) {
            setUpgradeTickInterval(minimalTickInterval);
        }
    }

    public void updateMinimalTickInterval(ItemStack newStack) {
        if(level != null && level.isClientSide) return;

        boolean applyLowestTickInterval = false;
        if(newStack.getItem() instanceof UpgradeItem upgradeItem) {
            if(upgradeItem.isTickingUpgrade()) {
                if(NbtHelper.getOrDefault(newStack, ModDataHelper.UPGRADE_ENABLED, true)) {
                    int tickInterval = getUpgradeTickInterval();
                    if(NbtHelper.has(newStack, ModDataHelper.COOLDOWN)) {
                        tickInterval = NbtHelper.get(newStack, ModDataHelper.COOLDOWN);
                    }
                    if(!canUpgradeTick() || tickInterval < getUpgradeTickInterval()) {
                        setUpgradeTickInterval(tickInterval);
                    } else if(tickInterval > getUpgradeTickInterval()) {
                        applyLowestTickInterval = true;
                    }
                } else {
                    applyLowestTickInterval = true;
                }
            }
        } else {
            applyLowestTickInterval = true;
        }

        if(canUpgradeTick()) {
            if(!hasTickingUpgrade()) {
                removeUpgradeTickInterval();
            } else if(applyLowestTickInterval) {
                applyLowestTickInterval();
            }
        }
    }

    private ItemStackHandler createUpgradeHandler(int size, int dataId) {
        return new ItemStackHandler(size) {
            @Override
            protected void onContentsChanged(int slot) {
                setSlotChanged(slot, getStackInSlot(slot), dataId);

                //Menu and screen updates
                if(!getPlayersUsing().isEmpty()) {
                    getUpgradeManager().detectedChange(upgradesTracker, slot);
                }

                updateMinimalTickInterval(getStackInSlot(slot));

                //Update client
                saveHandler.run();
            }

            @Override
            public int getSlotLimit(int slot) {
                return 1;
            }

            @Override
            public boolean isItemValid(int slot, @NotNull ItemStack stack) {
                boolean isValid = true;
                //Check if upgrade is already present
                for(int i = 0; i < this.getSlots(); i++) {
                    if(getStackInSlot(i).getItem() == stack.getItem()) {
                        isValid = false;
                        break;
                    }
                }
                if(!isValid) {
                    return false;
                }
                if(stack.getItem() instanceof TanksUpgradeItem) {
                    isValid = TanksUpgradeItem.canBePutInBackpack(getBackpackTankCapacity(), stack);
                }
                if(!checkIfUpgradeValid(stack)) {
                    isValid = false;
                }
                return isValid;
            }

            public boolean checkIfUpgradeValid(ItemStack upgradeStack) {
                if(upgradeStack.getItem() instanceof UpgradeItem upgradeItem) {
                    Player player = getPlayersUsing().isEmpty() ? null : getPlayersUsing().get(0);
                    if(player == null) {
                        return false;
                    }
                    return upgradeItem.isEnabled(player.level().enabledFeatures());
                }
                return false;
            }
        };
    }

    public static boolean isSizeInitialized(ItemStack stack) {
        return NbtHelper.has(stack, ModDataHelper.STORAGE_SLOTS) && NbtHelper.has(stack, ModDataHelper.UPGRADE_SLOTS) && NbtHelper.has(stack, ModDataHelper.TOOL_SLOTS);
    }

    public static void initializeSize(ItemStack stack) {
        Tiers.Tier tier = Tiers.LEATHER;
        if(NbtHelper.has(stack, ModDataHelper.TIER)) {
            tier = Tiers.of((int)NbtHelper.get(stack, ModDataHelper.TIER));
        } else {
            NbtHelper.set(stack, ModDataHelper.TIER, Tiers.LEATHER.getOrdinal());
        }
        if(!NbtHelper.has(stack, ModDataHelper.STORAGE_SLOTS)) {
            NbtHelper.set(stack, ModDataHelper.STORAGE_SLOTS, tier.getStorageSlots());
        }
        if(!NbtHelper.has(stack, ModDataHelper.UPGRADE_SLOTS)) {
            NbtHelper.set(stack, ModDataHelper.UPGRADE_SLOTS, tier.getUpgradeSlots());
        }
        if(!NbtHelper.has(stack, ModDataHelper.TOOL_SLOTS)) {
            NbtHelper.set(stack, ModDataHelper.TOOL_SLOTS, tier.getToolSlots());
        }
    }

    public void initializeSleepingBag(ItemStack stack) {
        if(TravelersBackpackConfig.serverSpec.isLoaded()) {
            if(!TravelersBackpackConfig.SERVER.backpackUpgrades.enableSleepingBag.get()) {
                if(!NbtHelper.has(stack, ModDataHelper.SLEEPING_BAG_COLOR)) {
                    NbtHelper.set(stack, ModDataHelper.SLEEPING_BAG_COLOR, -1);
                }
            }
        }
    }

    //Used if slots are removed/added - reconstructs modifiable slots & updates screen
    public void requestMenuAndScreenUpdate() {
        requestMenuUpdate();
        requestScreenUpdate();
    }

    public void requestMenuAndScreenUpdate(int slot) {
        requestMenuUpdate(slot);
        requestScreenUpdate();
    }

    public void requestMenuUpdate() {
        if(!getPlayersUsing().isEmpty()) {
            getPlayersUsing().stream().filter(player -> player.containerMenu instanceof BackpackBaseMenu).forEach(player -> ((BackpackBaseMenu)player.containerMenu).rebuildModifiableSlots());
        }
    }

    public void requestMenuUpdate(int slot) {
        if(!getPlayersUsing().isEmpty()) {
            getPlayersUsing().stream().filter(player -> player.containerMenu instanceof BackpackBaseMenu).forEach(player -> ((BackpackBaseMenu)player.containerMenu).updateModifiableSlotsPosition(slot));
        }
    }

    public void requestScreenUpdate() {
        if(!getPlayersUsing().isEmpty() && !getPlayersUsing().stream().filter(player -> player.level().isClientSide).toList().isEmpty()) {
            if(Minecraft.getInstance().screen instanceof BackpackScreen screen) {
                screen.updateScreen(false);
            }
        }
    }

    public static void tickForBlockEntity(BackpackBlockEntity backpackBlockEntity) {
        BackpackWrapper wrapper = backpackBlockEntity.getWrapper();
        if(wrapper != BackpackWrapper.DUMMY) {
            if(wrapper.hasTickingUpgrade()) {
                int ticks = (int)backpackBlockEntity.getLevel().getGameTime();
                int upgradeTicks = wrapper.getUpgradeTickInterval();
                if(upgradeTicks == 0) return;

                if(ticks % upgradeTicks == 0) {
                    wrapper.getUpgradeManager().upgrades.forEach(upgradeBase -> {
                        if(upgradeBase instanceof ITickableUpgrade tickable) {
                            boolean tick = true;
                            if(upgradeBase instanceof IEnable enable) {
                                tick = enable.isEnabled(upgradeBase);
                            }
                            if(tick) {
                                tickable.tick(null, backpackBlockEntity.getLevel(), backpackBlockEntity.getBlockPos(), ticks);
                            }
                        }
                    });
                }
            }

            if(BackpackAbilities.isOnList(BackpackAbilities.BLOCK_ABILITIES_LIST, wrapper.getBackpackStack()) && wrapper.isAbilityEnabled()) {
                boolean decreaseCooldown = BackpackAbilities.ABILITIES.abilityTickBlock(backpackBlockEntity);
                if(wrapper.getCooldown() > 0) {
                    if(decreaseCooldown) {
                        wrapper.decreaseCooldown();
                    }
                }
            }
        }
    }

    @Nullable
    public static BackpackWrapper getBackpackWrapper(Player player, ItemStack backpack, int[] dataLoad) {
        if(CapabilityUtils.isWearingBackpack(player)) {
            if(player.containerMenu instanceof BackpackItemMenu menu && menu.getWrapper().getScreenID() == Reference.WEARABLE_SCREEN_ID) {
                return menu.getWrapper();
            } else {
                for(Player otherPlayer : player.level().players()) {
                    if(otherPlayer.containerMenu instanceof BackpackItemMenu menu && menu.getWrapper().isOwner(player) && menu.getWrapper().getScreenID() == Reference.WEARABLE_SCREEN_ID) {
                        return menu.getWrapper();
                    }
                }
                return new BackpackWrapper(backpack, Reference.WEARABLE_SCREEN_ID, player, player.level(), dataLoad);
            }
        }
        return null;
    }

    public static void tick(ItemStack stack, Player player, boolean integration) {
        if(!integration) {
            if(TravelersBackpack.enableIntegration()) return;
        }

        if(player.isAlive() && CapabilityUtils.isWearingBackpack(player)) {
            int ticks = (int)player.level().getGameTime();

            if(BackpackAbilities.isOnList(BackpackAbilities.ITEM_ABILITIES_LIST, CapabilityUtils.getWearingBackpack(player))) {
                if(BackpackAbilities.isAbilityEnabledInConfig(stack)) {
                    if(NbtHelper.getOrDefault(stack, ModDataHelper.ABILITY_ENABLED, TravelersBackpackConfig.SERVER.backpackAbilities.forceAbilityEnabled.get())) {
                        boolean decreaseCooldown = BackpackAbilities.ABILITIES.abilityTick(stack, player);
                        if(NbtHelper.getOrDefault(stack, ModDataHelper.COOLDOWN, 0) > 0) {
                            BackpackWrapper wrapper;
                            if(ticks % 100 == 0) {
                                if(decreaseCooldown) {
                                    wrapper = CapabilityUtils.getBackpackWrapper(player, stack, CapabilityUtils.NO_ITEMS.get());
                                    int cooldown = wrapper.getCooldown();
                                    if(player.level().isClientSide) return;
                                    if(cooldown - 100 < 0) {
                                        wrapper.setCooldown(0);
                                    } else {
                                        wrapper.setCooldown(cooldown - 100);
                                    }
                                }
                            }
                        }
                    } else { //Tick cooldown even if ability switched off
                        if(NbtHelper.getOrDefault(stack, ModDataHelper.COOLDOWN, 0) > 0) {
                            BackpackWrapper wrapper;
                            if(ticks % 100 == 0) {
                                wrapper = CapabilityUtils.getBackpackWrapper(player, stack, CapabilityUtils.NO_ITEMS.get());
                                int cooldown = wrapper.getCooldown();
                                if(player.level().isClientSide) return;
                                if(cooldown - 100 < 0) {
                                    wrapper.setCooldown(0);
                                } else {
                                    wrapper.setCooldown(cooldown - 100);
                                }
                            }
                        }
                    }
                }
            } else if(NbtHelper.getOrDefault(stack, ModDataHelper.ABILITY_ENABLED, false)) {
                NbtHelper.set(stack, ModDataHelper.ABILITY_ENABLED, false);
            }
            if(NbtHelper.has(stack, ModDataHelper.UPGRADE_TICK_INTERVAL)) {
                int upgradeTicks = NbtHelper.get(stack, ModDataHelper.UPGRADE_TICK_INTERVAL);
                if(upgradeTicks == 0) return;
                BackpackWrapper wrapper;
                if(ticks % upgradeTicks == 0) {
                    wrapper = CapabilityUtils.getBackpackWrapper(player, stack, CapabilityUtils.UPGRADES_ONLY.get());
                    wrapper.getUpgradeManager().upgrades.forEach(upgradeBase -> {
                        if(upgradeBase instanceof ITickableUpgrade tickable) {
                            boolean tick = true;
                            if(upgradeBase instanceof IEnable enable) {
                                tick = enable.isEnabled(upgradeBase);
                            }
                            if(tick) {
                                tickable.tick(player, player.level(), player.blockPosition(), ticks);
                            }
                        }
                    });
                }
            }
        }
    }

    public void converter(ItemStack stack, int storageSlots, int toolSlots) {
        if(NbtHelper.has(stack, ModDataHelper.BACKPACK_CONTAINER)) {
            if(storageSlots != ((NonNullList<ItemStack>)NbtHelper.get(stack, ModDataHelper.BACKPACK_CONTAINER)).size()) {
                stack.getTag().put(ModDataHelper.BACKPACK_CONTAINER, NbtHelper.expandTag(stack, ModDataHelper.BACKPACK_CONTAINER, storageSlots));
            }
        }

        if(NbtHelper.has(stack, ModDataHelper.TOOLS_CONTAINER)) {
            if(toolSlots != ((NonNullList<ItemStack>)NbtHelper.get(stack, ModDataHelper.TOOLS_CONTAINER)).size()) {
                stack.getTag().put(ModDataHelper.TOOLS_CONTAINER, NbtHelper.expandTag(stack, ModDataHelper.TOOLS_CONTAINER, toolSlots));
            }
        }

        //Old Data Conversion (Should not run in regular case)
        if(NbtHelper.has(stack, ModDataHelper.LEFT_TANK) || NbtHelper.has(stack, ModDataHelper.RIGHT_TANK)) {
            CompoundTag oldTank = NbtHelper.has(stack, ModDataHelper.LEFT_TANK) ? stack.getTag().getCompound(ModDataHelper.LEFT_TANK) : new CompoundTag();
            CompoundTag oldTank2 = NbtHelper.has(stack, ModDataHelper.RIGHT_TANK) ? stack.getTag().getCompound(ModDataHelper.RIGHT_TANK) : new CompoundTag();
            FluidStack leftFluidStack = FluidStack.EMPTY;
            FluidStack rightFluidStack = FluidStack.EMPTY;

            if(!oldTank.isEmpty()) {
                FluidStack fluidStack = FluidStack.loadFluidStackFromNBT(oldTank);
                if(!fluidStack.isEmpty()) {
                    leftFluidStack = fluidStack;
                }
            }
            if(!oldTank2.isEmpty()) {
                FluidStack fluidStack = FluidStack.loadFluidStackFromNBT(oldTank2);
                if(!fluidStack.isEmpty()) {
                    rightFluidStack = fluidStack;
                }
            }
            ItemStack oldTanks = ModItems.TANKS_UPGRADE.get().getDefaultInstance();
            NbtHelper.set(oldTanks, ModDataHelper.FLUIDS, new Fluids(leftFluidStack, rightFluidStack));
            this.setStarterUpgrade(oldTanks);

            stack.getTag().remove(ModDataHelper.LEFT_TANK);
            stack.getTag().remove(ModDataHelper.RIGHT_TANK);
        }

        if(stack.hasTag() && stack.getTag().contains("CraftingInventory")) {
            ItemStack craftingUpgrade = ModItems.CRAFTING_UPGRADE.get().getDefaultInstance();
            ItemStackHandler craftingInventory = new ItemStackHandler(9);
            craftingInventory.deserializeNBT(stack.getTag().getCompound("CraftingInventory"));
            NbtHelper.set(craftingUpgrade, ModDataHelper.BACKPACK_CONTAINER, craftingInventory);
            this.setStarterUpgrade(craftingUpgrade);

            stack.getTag().remove("CraftingInventory");
        }
    }
}

package com.tiviacz.travelersbackpack.inventory;

import com.mojang.datafixers.util.Pair;
import com.tiviacz.travelersbackpack.inventory.upgrades.voiding.VoidUpgrade;
import com.tiviacz.travelersbackpack.util.ItemStackUtils;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.items.IItemHandlerModifiable;
import net.minecraftforge.items.ItemStackHandler;
import org.jetbrains.annotations.NotNull;

/**
 * Custom ItemStackHandler for Traveler's Backpack block entity interactions with hoppers, pipes etc. that respects unsortable and memory slots :)
 */
public class StorageAccessWrapper implements IItemHandlerModifiable {
    public final BackpackWrapper wrapper;
    public final ItemStackHandler parent;
    public boolean skipVoiding = false;

    public StorageAccessWrapper(BackpackWrapper wrapper, ItemStackHandler parent, boolean skipVoiding) {
        this(wrapper, parent);
        this.skipVoiding = skipVoiding;
    }

    public StorageAccessWrapper(BackpackWrapper wrapper, ItemStackHandler parent) {
        this.wrapper = wrapper;
        this.parent = parent;
    }

    @Override
    public void setStackInSlot(int slot, @NotNull ItemStack stack) {
        parent.setStackInSlot(slot, stack);
    }

    @Override
    public int getSlots() {
        return parent.getSlots();
    }

    @Override
    public @NotNull ItemStack getStackInSlot(int slot) {
        return parent.getStackInSlot(slot);
    }

    @Override
    public @NotNull ItemStack insertItem(int slot, @NotNull ItemStack stack, boolean simulate) {
        //Voiding
        if(!skipVoiding && tryVoiding(stack)) {
            if(!simulate) {
                return ItemStack.EMPTY;
            }
        }
        //Try inserting to memory slots first
        if(!wrapper.getMemorySlots().isEmpty()) {
            for(Pair<Integer, Pair<ItemStack, Boolean>> memorizedStack : wrapper.getMemorySlots()) {
                if(memorizedStack.getSecond().getFirst().getItem() != stack.getItem()) {
                    continue;
                }
                int result = matchesStack(stack, memorizedStack);
                if(result != -1) {
                    stack = parent.insertItem(result, stack, simulate);
                    if(stack.isEmpty()) {
                        return ItemStack.EMPTY;
                    }
                }
            }
        }
        return wrapper.getUnsortableSlots().contains(slot) ? stack : parent.insertItem(slot, stack, simulate);
    }

    public int matchesStack(ItemStack inserted, Pair<Integer, Pair<ItemStack, Boolean>> memorizedStack) {
        if(memorizedStack.getSecond().getSecond()) {
            return ItemStackUtils.isSameItemSameTags(inserted, memorizedStack.getSecond().getFirst()) ? memorizedStack.getFirst() : -1;
        } else {
            return ItemStack.isSameItem(inserted, memorizedStack.getSecond().getFirst()) ? memorizedStack.getFirst() : -1;
        }
    }

    public boolean tryVoiding(ItemStack stack) {
        return wrapper.getUpgradeManager().getUpgrade(VoidUpgrade.class).map(voidUpgrade -> voidUpgrade.canVoid(stack)).orElse(false);
    }

    @Override
    public @NotNull ItemStack extractItem(int slot, int amount, boolean simulate) {
        return wrapper.getUnsortableSlots().contains(slot) ? ItemStack.EMPTY : parent.extractItem(slot, amount, simulate);
    }

    @Override
    public int getSlotLimit(int slot) {
        return parent.getSlotLimit(slot);
    }

    @Override
    public boolean isItemValid(int slot, @NotNull ItemStack stack) {
        return parent.isItemValid(slot, stack);
    }
}

package com.tiviacz.travelersbackpack.inventory;

import com.tiviacz.travelersbackpack.config.TravelersBackpackConfig;
import com.tiviacz.travelersbackpack.init.ModItems;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.Items;

public class Tiers {
    public static final Tier LEATHER = new Tier("leather", (9 * 3), 2, 2, 1000);
    public static final Tier IRON = new Tier("iron", (9 * 5), 3, 3, 1000);
    public static final Tier GOLD = new Tier("gold", (9 * 7), 4, 4, 1000);
    public static final Tier DIAMOND = new Tier("diamond", (9 * 9), 5, 5, 1000);
    public static final Tier NETHERITE = new Tier("netherite", (9 * 11), 6, 6, 1000);

    public static class Tier {
        public final String name;
        public int toolSlots;
        public final int storageSlots;
        public final int upgradeSlots;
        public final int tankCapacityPerRow;

        public Tier(String name, int storageSlots, int upgradeSlots, int toolSlots, int tankCapacityPerRow) {
            this.name = name;
            this.storageSlots = storageSlots;
            this.upgradeSlots = upgradeSlots;
            this.toolSlots = toolSlots;
            this.tankCapacityPerRow = tankCapacityPerRow;
        }

        public String getName() {
            return this.name;
        }

        public Component getLocalizedName() {
            return Component.translatable("tier.travelersbackpack." + this.name);
        }

        public int getStorageSlots() {
            if(this == LEATHER) return TravelersBackpackConfig.SERVER.backpackSettings.leather.inventorySlotCount.get();
            if(this == IRON) return TravelersBackpackConfig.SERVER.backpackSettings.iron.inventorySlotCount.get();
            if(this == GOLD) return TravelersBackpackConfig.SERVER.backpackSettings.gold.inventorySlotCount.get();
            if(this == DIAMOND) return TravelersBackpackConfig.SERVER.backpackSettings.diamond.inventorySlotCount.get();
            if(this == NETHERITE)
                return TravelersBackpackConfig.SERVER.backpackSettings.netherite.inventorySlotCount.get();
            return this.storageSlots;
        }

        public int getUpgradeSlots() {
            if(this == LEATHER) return TravelersBackpackConfig.SERVER.backpackSettings.leather.upgradeSlotCount.get();
            if(this == IRON) return TravelersBackpackConfig.SERVER.backpackSettings.iron.upgradeSlotCount.get();
            if(this == GOLD) return TravelersBackpackConfig.SERVER.backpackSettings.gold.upgradeSlotCount.get();
            if(this == DIAMOND) return TravelersBackpackConfig.SERVER.backpackSettings.diamond.upgradeSlotCount.get();
            if(this == NETHERITE)
                return TravelersBackpackConfig.SERVER.backpackSettings.netherite.upgradeSlotCount.get();
            return this.upgradeSlots;
        }

        public int getToolSlots() {
            if(this == LEATHER) return TravelersBackpackConfig.SERVER.backpackSettings.leather.toolSlotCount.get();
            if(this == IRON) return TravelersBackpackConfig.SERVER.backpackSettings.iron.toolSlotCount.get();
            if(this == GOLD) return TravelersBackpackConfig.SERVER.backpackSettings.gold.toolSlotCount.get();
            if(this == DIAMOND) return TravelersBackpackConfig.SERVER.backpackSettings.diamond.toolSlotCount.get();
            if(this == NETHERITE) return TravelersBackpackConfig.SERVER.backpackSettings.netherite.toolSlotCount.get();
            return this.toolSlots;
        }

        public int getTankCapacityPerRow() {
            if(this == LEATHER) return TravelersBackpackConfig.SERVER.backpackSettings.leather.tankCapacityPerRow.get();
            if(this == IRON) return TravelersBackpackConfig.SERVER.backpackSettings.iron.tankCapacityPerRow.get();
            if(this == GOLD) return TravelersBackpackConfig.SERVER.backpackSettings.gold.tankCapacityPerRow.get();
            if(this == DIAMOND) return TravelersBackpackConfig.SERVER.backpackSettings.diamond.tankCapacityPerRow.get();
            if(this == NETHERITE)
                return TravelersBackpackConfig.SERVER.backpackSettings.netherite.tankCapacityPerRow.get();
            return this.tankCapacityPerRow;
        }

        public Tier getNextTier() {
            if(this == LEATHER) return IRON;
            if(this == IRON) return GOLD;
            if(this == GOLD) return DIAMOND;
            if(this == DIAMOND) return NETHERITE;
            return LEATHER;
        }

        public int getOrdinal() {
            if(this == LEATHER) return 0;
            if(this == IRON) return 1;
            if(this == GOLD) return 2;
            if(this == DIAMOND) return 3;
            if(this == NETHERITE) return 4;
            return -1;
        }

        public Item getTierUpgradeIngredient() {
            if(this == LEATHER) return ModItems.IRON_TIER_UPGRADE.get();
            if(this == IRON) return ModItems.GOLD_TIER_UPGRADE.get();
            if(this == GOLD) return ModItems.DIAMOND_TIER_UPGRADE.get();
            if(this == DIAMOND) return ModItems.NETHERITE_TIER_UPGRADE.get();
            return Items.AIR;
        }
    }

    public static Tier of(String name) {
        return switch(name) {
            case "leather" -> Tiers.LEATHER;
            case "iron" -> Tiers.IRON;
            case "gold" -> Tiers.GOLD;
            case "diamond" -> Tiers.DIAMOND;
            case "netherite" -> Tiers.NETHERITE;
            default -> Tiers.LEATHER;
        };
    }

    public static Tier of(int ordinal) {
        return switch(ordinal) {
            case 0 -> Tiers.LEATHER;
            case 1 -> Tiers.IRON;
            case 2 -> Tiers.GOLD;
            case 3 -> Tiers.DIAMOND;
            case 4 -> Tiers.NETHERITE;
            default -> Tiers.LEATHER;
        };
    }
}

package com.tiviacz.travelersbackpack.inventory;

import com.google.common.collect.BiMap;
import com.google.common.collect.HashBiMap;
import com.tiviacz.travelersbackpack.init.ModDataHelper;
import com.tiviacz.travelersbackpack.inventory.upgrades.IEnable;
import com.tiviacz.travelersbackpack.inventory.upgrades.ITickableUpgrade;
import com.tiviacz.travelersbackpack.inventory.upgrades.UpgradeBase;
import com.tiviacz.travelersbackpack.items.upgrades.UpgradeItem;
import com.tiviacz.travelersbackpack.util.NbtHelper;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.items.ItemStackHandler;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicBoolean;

public class UpgradeManager {
    public final BackpackWrapper wrapper;
    public final ItemStackHandler upgradesHandler;
    public BiMap<Integer, Optional<UpgradeBase<?>>> mappedUpgrades;
    public List<UpgradeBase<?>> upgrades = new ArrayList<>();

    public UpgradeManager(BackpackWrapper wrapper) {
        this.wrapper = wrapper;
        this.upgradesHandler = wrapper.getUpgrades();
        this.mappedUpgrades = HashBiMap.create();
        initializeUpgrades();
    }

    public BackpackWrapper getWrapper() {
        return this.wrapper;
    }

    public ItemStackHandler getUpgradesHandler() {
        return this.upgradesHandler;
    }

    public boolean hasUpgradeInSlot(int slot) {
        return this.mappedUpgrades.containsKey(slot);
    }

    public <T extends UpgradeBase<T>> Optional<T> getUpgrade(Class<T> upgradeClass) {
        return upgrades.stream()
                .filter(upgradeClass::isInstance)
                .map(upgradeClass::cast)
                .findFirst();
    }

    public boolean canAddUpgrade(UpgradeItem upgradeItem) {
        return upgrades.stream().noneMatch(u -> u.getClass().equals(upgradeItem.getUpgradeClass()));
    }

    public boolean invalidateUpgrade(int slot) {
        Optional<UpgradeBase<?>> upgrade = this.mappedUpgrades.get(slot);

        //Update upgrade tracker
        getWrapper().upgradesTracker.setStackInSlot(slot, ItemStack.EMPTY);

        //Error - item in slot is not an upgrade, just return
        if(upgrade == null) {
            return false;
        }

        upgrade.ifPresent(upg -> {
            this.mappedUpgrades.remove(slot);
            upg.remove();
            upgrades.remove(upg);
        });
        return true;
    }

    public void initializeUpgrades() {
        for(int i = 0; i < getUpgradesHandler().getSlots(); i++) {
            applyUpgrade(i);
        }
    }

    public void detectedChange(ItemStackHandler tracker, int slot) {
        boolean updatePosition = false;
        boolean needsUpdate = applyUpgrade(slot);

        //Update if tab changed status
        boolean changedTabStatus = getTabStatus(tracker.getStackInSlot(slot)) != getTabStatus(getUpgradesHandler().getStackInSlot(slot));
        boolean isTagSelector = isTagSelector(getUpgradesHandler().getStackInSlot(slot), tracker.getStackInSlot(slot));

        if(changedTabStatus || isTagSelector) {
            if(!needsUpdate && changedTabStatus) {
                updatePosition = true;
            }
            needsUpdate = true;
            ItemStack stackToSet = getUpgradesHandler().getStackInSlot(slot).copy();
            tracker.setStackInSlot(slot, stackToSet);
        }

        if(mappedUpgrades.containsKey(slot)) {
            if(!(getUpgradesHandler().getStackInSlot(slot).getItem() instanceof UpgradeItem)) {
                needsUpdate = this.invalidateUpgrade(slot);
                updatePosition = false;
            }
        }

        //Update menu and screen
        if(needsUpdate) {
            if(!getWrapper().getPlayersUsing().isEmpty()) {
                getWrapper().getPlayersUsing().stream().filter(player -> !player.level().isClientSide).forEach(player -> player.containerMenu.broadcastChanges());
            }
            if(!updatePosition) {
                getWrapper().requestMenuAndScreenUpdate();
            } else {
                getWrapper().requestMenuAndScreenUpdate(slot);
            }
        }
    }

    public boolean applyUpgrade(int slot) {
        AtomicBoolean atomic = new AtomicBoolean(false);
        ItemStack upgradeStack = getUpgradesHandler().getStackInSlot(slot);
        if(upgradeStack.getItem() instanceof UpgradeItem upgradeItem) {
            if(canAddUpgrade(upgradeItem)) {
                upgradeItem.getUpgrade().apply(this, slot, upgradeStack).ifPresent(upgrade -> {
                    this.upgrades.add(upgrade);
                    this.mappedUpgrades.put(slot, Optional.of(upgrade));
                    atomic.set(true);
                });
            }
        }
        return atomic.get();
    }

    public boolean getTabStatus(ItemStack stack) {
        return NbtHelper.getOrDefault(stack, ModDataHelper.TAB_OPEN, false);
    }

    public boolean isTagSelector(ItemStack current, ItemStack tracker) {
        return isTagSelector(current) ^ isTagSelector(tracker);
    }

    public boolean isTagSelector(ItemStack stack) {
        return NbtHelper.getOrDefault(stack, ModDataHelper.FILTER_SETTINGS, List.of(1, 0, 1)).get(1) == 2;
    }

    public boolean hasTickingUpgrade() {
        return this.upgrades.stream()
                .filter(upgradeBase -> upgradeBase instanceof ITickableUpgrade && upgradeBase instanceof IEnable)
                .anyMatch(upgrade -> ((IEnable)upgrade).isEnabled(upgrade));
    }
}

package com.tiviacz.travelersbackpack.inventory.upgrades;

import com.tiviacz.travelersbackpack.init.ModDataHelper;
import com.tiviacz.travelersbackpack.inventory.UpgradeManager;
import com.tiviacz.travelersbackpack.inventory.upgrades.filter.IFilterSlots;
import com.tiviacz.travelersbackpack.util.NbtHelper;
import net.minecraft.world.item.ItemStack;

import java.util.function.Consumer;

public abstract class UpgradeBase<T> implements IUpgrade<T> {
    public UpgradeManager upgradeManager;
    public int dataHolderSlot;
    public Point openTabSize;

    public UpgradeBase(UpgradeManager manager, int dataHolderSlot, Point openTabSize) {
        this.upgradeManager = manager;
        this.dataHolderSlot = dataHolderSlot;
        this.openTabSize = openTabSize;
    }

    public UpgradeManager getUpgradeManager() {
        return this.upgradeManager;
    }

    public int getDataHolderSlot() {
        return this.dataHolderSlot;
    }

    @Override
    public boolean isTabOpened() {
        return NbtHelper.getOrDefault(this.upgradeManager.getUpgradesHandler().getStackInSlot(this.dataHolderSlot), ModDataHelper.TAB_OPEN, false);
    }

    public ItemStack getDataHolderStack() {
        return this.upgradeManager.getUpgradesHandler().getStackInSlot(this.dataHolderSlot);
    }

    @Override
    public Point getTabSize() {
        if(isTabOpened()) {
            if(this instanceof IFilterSlots slots) {
                int x = this.openTabSize.x();
                if(slots.getSlotsInRow() > 3) {
                    x += (slots.getSlotsInRow() - 3) * 18;
                }
                return new Point(x, this.openTabSize.y() + (18 * slots.getRows()));
            }
            return this.openTabSize;
        }
        return new Point(24, 24);
    }

    public void updateDataHolderUnchecked(Consumer<ItemStack> updater) {
        ItemStack dataHolderStack = getDataHolderStack().copy();

        //TS fix prevent
        if(dataHolderStack.isEmpty()) return;

        updater.accept(dataHolderStack);
        getUpgradeManager().getUpgradesHandler().setStackInSlot(getDataHolderSlot(), dataHolderStack);
    }

    public void updateDataHolderUnchecked(String dataKey, Object value) {
        ItemStack dataHolderStack = getDataHolderStack().copy();

        //TS fix prevent
        if(dataHolderStack.isEmpty()) return;

        NbtHelper.set(dataHolderStack, dataKey, value);
        getUpgradeManager().getUpgradesHandler().setStackInSlot(getDataHolderSlot(), dataHolderStack);
    }

    public void setCooldown(int cooldown) {
        ItemStack dataHolderStack = getDataHolderStack().copy();
        NbtHelper.set(dataHolderStack, ModDataHelper.COOLDOWN, cooldown);
        getUpgradeManager().getUpgradesHandler().setStackInSlot(getDataHolderSlot(), dataHolderStack);
    }

    public int getCooldown() {
        return NbtHelper.getOrDefault(getDataHolderStack(), ModDataHelper.COOLDOWN, 100);
    }

    public boolean hasCooldown() {
        return NbtHelper.has(getDataHolderStack(), ModDataHelper.COOLDOWN);
    }
}

